steps.script:
function transform(ctx) {
  var MAP = { "移动": "cmcc", "联通": "unicom", "电信": "telecom" };
  var isp = (ctx.isp || "").trim();
  var s = "";
  if (isp) { s = MAP[isp] !== undefined ? MAP[isp] : (isp.charAt(0) === "@" ? isp.substring(1) : ""); }
  var full = (ctx.username || "") + (s ? "@" + s : "");
  var mac = (ctx.local_mac || "").replace(/:/g, "").toLowerCase();
  var ts = String(Math.floor(now_ms()));
  return { ua: url_encode(full), ep: url_encode(ctx.password || ""), mac: mac, ts: ts, callback: "dr" + ts };
}
